import Foundation
import XCTest
@testable import ColorComposerCore

/// Replays the v1 golden vectors generated by color_matching's
/// `mix parity.generate`. The fixture is intentionally copied verbatim so a
/// scorer change cannot silently alter client/server selection semantics.
final class WeightedSquaredErrorParityCorpusTests: XCTestCase {
    func testV1CorpusMatchesScoresSelectionsAndTieEvidence() throws {
        let corpus = try JSONDecoder().decode(Corpus.self, from: try fixtureData())

        XCTAssertEqual(corpus.algorithmVersion, 1)
        XCTAssertEqual(corpus.scorer, "ColorMatching.WeightedSquaredError")
        XCTAssertEqual(corpus.selection, "earliest-index-wins")
        XCTAssertEqual(corpus.missingPolicy, "excluded-when-any-positive-weight-channel-missing")

        for scenario in corpus.scenarios {
            assertScenario(scenario)
        }
    }

    private func assertScenario(_ scenario: Scenario, file: StaticString = #filePath, line: UInt = #line) {
        let scorer = WeightedSquaredErrorScorer()
        let weights = ChannelWeights(channels: scenario.weights)
        let target = TargetResponseVector(scenario.target.channels.lightingConditions)
        let scores = scenario.palette.map { entry in
            scorer.score(candidate: entry.paletteColor, target: target, weights: weights)
        }

        XCTAssertEqual(scores.count, scenario.expected.scores.count, scenario.id, file: file, line: line)
        for (index, pair) in zip(scores, scenario.expected.scores).enumerated() {
            let (actual, expected) = pair
            XCTAssertEqual(expected.index, index, scenario.id, file: file, line: line)
            XCTAssertEqual(actual, expected.scorerResult, "\(scenario.id) candidate \(expected.index)", file: file, line: line)
        }

        let selected = scores.enumerated().compactMap { index, score -> (Int, Double)? in
            guard case .score(let value) = score else { return nil }
            return (index, value)
        }.min { $0.1 < $1.1 }

        XCTAssertEqual(selected?.0, scenario.expected.selectedIndex, scenario.id, file: file, line: line)
        XCTAssertEqual(selected?.1, scenario.expected.error, scenario.id, file: file, line: line)
        XCTAssertEqual(selected.map { scenario.palette[$0.0].hexColor }, scenario.expected.selectedHexColor, scenario.id, file: file, line: line)

        let tiedIndices = scores.enumerated().compactMap { index, score -> Int? in
            guard case .score(let value) = score, value == selected?.1 else { return nil }
            return index
        }
        XCTAssertEqual(tiedIndices, scenario.expected.tiedIndices, scenario.id, file: file, line: line)
        let tieBroke: Bool? = selected == nil ? nil : tiedIndices.count > 1
        XCTAssertEqual(tieBroke, scenario.expected.tieBroke, scenario.id, file: file, line: line)
    }

    private func fixtureData() throws -> Data {
        let testFile = URL(fileURLWithPath: #filePath)
        let fixture = testFile.deletingLastPathComponent()
            .appendingPathComponent("Fixtures/weighted-squared-error-v1.json")
        return try Data(contentsOf: fixture)
    }
}

private struct Corpus: Decodable {
    let algorithmVersion: Int
    let scorer: String
    let selection: String
    let missingPolicy: String
    let scenarios: [Scenario]
}

private struct Scenario: Decodable {
    let id: String
    let weights: [String: Double]
    let target: CorpusEntry
    let palette: [CorpusEntry]
    let expected: Expected
}

private struct CorpusEntry: Decodable {
    let hexColor: String
    let channels: [String: Double]

    var paletteColor: PaletteColor {
        PaletteColor(
            id: 0,
            hex: hexColor,
            rgb: RGBColor(hex: hexColor)!,
            responses: channels.lightingConditions.mapValues(IlluminationResponse.init(brightness:))
        )
    }
}

private struct Expected: Decodable {
    let scores: [ExpectedScore]
    let selectedIndex: Int?
    let selectedHexColor: String?
    let error: Double?
    let tieBroke: Bool?
    let tiedIndices: [Int]
}

private struct ExpectedScore: Decodable {
    let index: Int
    let score: ScoreValue

    var scorerResult: ScorerResult {
        switch score {
        case .excluded: return .excluded
        case .score(let value): return .score(value)
        }
    }
}

private enum ScoreValue: Decodable {
    case excluded
    case score(Double)

    init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let value = try? container.decode(Double.self) {
            self = .score(value)
        } else {
            XCTAssertEqual(try container.decode(String.self), "excluded")
            self = .excluded
        }
    }
}

private extension Dictionary where Key == String, Value == Double {
    var lightingConditions: [LightingCondition: Double] {
        reduce(into: [:]) { result, entry in
            guard let condition = LightingCondition(rawValue: entry.key) else { return }
            result[condition] = entry.value
        }
    }
}

private extension ChannelWeights {
    init(channels: [String: Double]) {
        self.init(
            white: channels["white", default: 0],
            red: channels["red", default: 0],
            green: channels["green", default: 0],
            blue: channels["blue", default: 0],
            lps: channels["lps", default: 0]
        )
    }
}
